package com.beeboee.magnot.server;import com.beeboee.magnot.network.MagnotNetwork;import com.beeboee.magnot.region.*;import com.beeboee.magnot.registry.MagnotItems;import net.minecraft.entity.player.ServerPlayerEntity;import net.minecraft.util.SoundCategory;import net.minecraft.util.SoundEvents;import net.minecraft.util.math.vector.Vector3d;import net.minecraft.world.server.ServerWorld;import java.util.*;public final class RegionActions{private RegionActions(){}public static boolean remove(ServerPlayerEntity p,UUID id){if(!(p.level instanceof ServerWorld)||p.getMainHandItem().getItem()!=MagnotItems.FERROUS_TUBE.get())return false;ServerWorld l=(ServerWorld)p.level;Vector3d a=p.getEyePosition(1),b=a.add(p.getLookAngle().scale(6));Optional<FerrousRegion>r=FerrousRegionSavedData.get(l).removeIntersectingById(id,a,b);if(!r.isPresent())return false;l.playSound(null,r.get().min(),SoundEvents.SLIME_BLOCK_BREAK,SoundCategory.BLOCKS,.5f,.75f);MagnotNetwork.syncDimension(l);return true;}}
